#!/usr/bin/env bash
set -euo pipefail

usage() {
  cat <<'USAGE'
Usage:
  bash apply_sc_lmcache_refactor.sh [--repo PATH] [--check]
  bash apply_sc_lmcache_refactor.sh [--repo PATH] --replace
  bash apply_sc_lmcache_refactor.sh [--repo PATH] --restore BACKUP_TAR_GZ

Default mode applies a unified Git patch and refuses to modify files if the
current source does not match the captured baseline. --replace deliberately
overwrites the complete target files from the embedded replacement tree.
Every modifying mode creates or uses a backup tarball.
USAGE
}

MODE=patch
REPO=""
RESTORE_ARCHIVE=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --repo)
      REPO="${2:?--repo requires a path}"
      shift 2
      ;;
    --check)
      MODE=check
      shift
      ;;
    --replace)
      MODE=replace
      shift
      ;;
    --restore)
      MODE=restore
      RESTORE_ARCHIVE="${2:?--restore requires a backup tar.gz}"
      shift 2
      ;;
    -h|--help)
      usage
      exit 0
      ;;
    *)
      echo "Unknown argument: $1" >&2
      usage >&2
      exit 2
      ;;
  esac
done

if [[ -z "$REPO" ]]; then
  if REPO=$(git rev-parse --show-toplevel 2>/dev/null); then
    :
  elif [[ -d /mnt/shared/gpfs/home/sriramc2/KV-Aware-vLLM/.git ]]; then
    REPO=/mnt/shared/gpfs/home/sriramc2/KV-Aware-vLLM
  else
    echo "Could not find the repository. Run from the repo or pass --repo PATH." >&2
    exit 2
  fi
fi
REPO=$(cd "$REPO" && pwd)

if [[ ! -d "$REPO/third_party/LMCache/lmcache/v1" ]]; then
  echo "Not a compatible KV-Aware-vLLM repository: $REPO" >&2
  exit 2
fi

TARGETS=(
  'local_repro/SC_LMCACHE_KNOBS.md'
  'local_repro/cpu_offload_lmcache_sriram.py'
  'local_repro/run_driver.sh'
  'local_repro/sbatch/01_h100_with_gnn.sbatch'
  'local_repro/sbatch/02_h100_wo_gnn.sbatch'
  'local_repro/sbatch/03_h100_all_datasets_250.sbatch'
  'local_repro/sbatch/2_l40_wo_gnn.sbatch'
  'local_repro/sc_lmcache_knobs.sh'
  'third_party/LMCache/lmcache/integration/vllm/vllm_v1_adapter.py'
  'third_party/LMCache/lmcache/v1/cache_engine.py'
  'third_party/LMCache/lmcache/v1/gpu_connector/gpu_connectors.py'
  'third_party/LMCache/lmcache/v1/lookup_client/lmcache_async_lookup_client.py'
  'third_party/LMCache/lmcache/v1/memory_management.py'
  'third_party/LMCache/lmcache/v1/sc_config.py'
  'third_party/LMCache/lmcache/v1/storage_backend/local_cpu_backend.py'
  'third_party/LMCache/lmcache/v1/storage_backend/local_disk_backend.py'
  'third_party/LMCache/lmcache/v1/storage_backend/storage_manager.py'
)

make_backup() {
  local stamp backup list_file
  stamp=$(date +%Y%m%d_%H%M%S)
  backup="${REPO}/../sc_lmcache_refactor_backup_${stamp}.tar.gz"
  list_file=$(mktemp)
  for path in "${TARGETS[@]}"; do
    [[ -e "$REPO/$path" || -L "$REPO/$path" ]] && printf '%s
' "$path" >> "$list_file"
  done
  tar -C "$REPO" -czf "$backup" -T "$list_file"
  rm -f "$list_file"
  printf '%s
' "$backup"
}

validate_tree() {
  local python_bin
  python_bin=python3
  if [[ -x /mnt/shared/gpfs/home/sriramc2/venvs/kvaware/bin/python ]]; then
    python_bin=/mnt/shared/gpfs/home/sriramc2/venvs/kvaware/bin/python
  elif [[ -x "$(dirname "$REPO")/venvs/kvaware/bin/python" ]]; then
    python_bin="$(dirname "$REPO")/venvs/kvaware/bin/python"
  fi

  SC_REPO="$REPO" "$python_bin" - <<'PY_VALIDATE'
from pathlib import Path
import os

root = Path(os.environ["SC_REPO"])
paths = [
    "local_repro/cpu_offload_lmcache_sriram.py",
    "third_party/LMCache/lmcache/integration/vllm/vllm_v1_adapter.py",
    "third_party/LMCache/lmcache/v1/cache_engine.py",
    "third_party/LMCache/lmcache/v1/gpu_connector/gpu_connectors.py",
    "third_party/LMCache/lmcache/v1/lookup_client/lmcache_async_lookup_client.py",
    "third_party/LMCache/lmcache/v1/memory_management.py",
    "third_party/LMCache/lmcache/v1/sc_config.py",
    "third_party/LMCache/lmcache/v1/storage_backend/local_cpu_backend.py",
    "third_party/LMCache/lmcache/v1/storage_backend/local_disk_backend.py",
    "third_party/LMCache/lmcache/v1/storage_backend/storage_manager.py",
]
for relative in paths:
    path = root / relative
    compile(path.read_text(encoding="utf-8"), str(path), "exec")
PY_VALIDATE

  bash -n "$REPO/local_repro/run_driver.sh"
  bash -n "$REPO/local_repro/sc_lmcache_knobs.sh"
  bash -n "$REPO/local_repro/sbatch/01_h100_with_gnn.sbatch"
  bash -n "$REPO/local_repro/sbatch/02_h100_wo_gnn.sbatch"
  bash -n "$REPO/local_repro/sbatch/03_h100_all_datasets_250.sbatch"
  bash -n "$REPO/local_repro/sbatch/2_l40_wo_gnn.sbatch"

  local legacy_scan=()
  local path
  for path in "${TARGETS[@]}"; do
    [[ "$path" == *.md ]] && continue
    legacy_scan+=("$REPO/$path")
  done
  if grep -RInE 'SRIRAM_KV_|SRIRAM_LONG_|SRIRAM_LMCACHE_DIR|LMCACHE_P0_|\bP0-[A-Z]|\[SRIRAM_' \
      "${legacy_scan[@]}" 2>/dev/null; then
    echo "Legacy active identifiers remain after refactor." >&2
    return 1
  fi
}

TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

cat > "$TMP/refactor.patch.b64" <<'PATCH_B64'
