TREE_B64
base64 -d "$TMP/replacement.tar.gz.b64" > "$TMP/replacement.tar.gz"

case "$MODE" in
  check)
    git -C "$REPO" apply --check --whitespace=nowarn "$TMP/refactor.patch"
    echo "Patch check passed for $REPO"
    ;;
  patch)
    git -C "$REPO" apply --check --whitespace=nowarn "$TMP/refactor.patch" || {
      cat >&2 <<'MSG'
The safe patch check failed. The active files have drifted from the captured
bundle. Nothing was changed. Review the separate .patch, upload the newer code
bundle, or deliberately rerun this script with --replace to overwrite the full
target files after a backup.
MSG
      exit 1
    }
    backup=$(make_backup)
    git -C "$REPO" apply --whitespace=nowarn "$TMP/refactor.patch"
    validate_tree
    echo "Applied SC LMCache refactor."
    echo "Backup: $backup"
    ;;
  replace)
    backup=$(make_backup)
    tar -C "$REPO" -xzf "$TMP/replacement.tar.gz"
    validate_tree
    echo "Replaced complete target files with the SC refactor."
    echo "Backup: $backup"
    ;;
  restore)
    if [[ ! -f "$RESTORE_ARCHIVE" ]]; then
      echo "Backup not found: $RESTORE_ARCHIVE" >&2
      exit 2
    fi
    for path in "${TARGETS[@]}"; do
      rm -rf "$REPO/$path"
    done
    tar -C "$REPO" -xzf "$RESTORE_ARCHIVE"
    echo "Restored target files from $RESTORE_ARCHIVE"
    ;;
esac
